def _rgb_pixel_sha256(image: Image.Image) -> str:
    """Return the normalized RGB pixel digest of *image*."""
    normalized = ImageOps.exif_transpose(image).convert("RGB")
    return hashlib.sha256(normalized.tobytes()).hexdigest()


def _marker_rgb_medians(signature: Mapping[str, Any]) -> list[list[int]]:
    cells = list(signature.get("rgb_cells") or [])
    return [
        [int(value) for value in list(cell.get("median_rgb") or [])[:3]]
        for cell in cells
        if isinstance(cell, Mapping)
    ]


def _media_row(path: Path, root: Path) -> dict[str, Any]:
    """Describe one stored photo by its pixels and its identity marker."""
    row = {
        "path": path,
        "relative_path": relative_media_path(path, root),
        "readable": False,
        "read_error": None,
        "dimensions": None,
        "rgb_pixel_sha256": None,
        "marker_detected": False,
        "marker_index": None,
        "detection_score": None,
        "identity_confidence": None,
        "marker_box": None,
        "marker_rgb_medians": [],
    }
    try:
        with Image.open(path) as handle:
            handle.load()
            normalized = ImageOps.exif_transpose(handle).convert("RGB")
            row["readable"] = True
            row["dimensions"] = list(normalized.size)
            row["rgb_pixel_sha256"] = _rgb_pixel_sha256(normalized)
            detection = detect_rgb_marker(normalized)
    except Exception as exc:
        row["read_error"] = f"{type(exc).__name__}: {exc}"
        return row
    if detection is not None:
        signature = detection.get("signature")
        row.update(
            {
                "marker_detected": True,
                "marker_index": detection.get("marker_index"),
                "detection_score": detection.get("score"),
                "identity_confidence": detection.get("identity_confidence"),
                "marker_box": list(detection.get("box") or []),
                "marker_rgb_medians": _marker_rgb_medians(
                    signature if isinstance(signature, Mapping) else {}
                ),
            }
        )
    return row


def read_simulator_library(simulator_root: Path) -> list[dict[str, Any]]:
    """Describe every stored photo below *simulator_root*."""
    return [_media_row(path, simulator_root) for path in simulator_media_files(simulator_root)]


def _locate_export(
    golden: Mapping[str, Any], rows: Sequence[Mapping[str, Any]]
) -> tuple[Mapping[str, Any] | None, list[str]]:
    """Return the one row whose pixels are the expected export, plus its matches."""
    digest = str(golden["rgb_pixel_sha256"])
    matches = [row for row in rows if row.get("rgb_pixel_sha256") == digest]
    names = [str(row.get("relative_path")) for row in matches]
    if len(matches) == 1:
        return matches[0], names
    return None, names


