class OpenPhotoEditTheaterVisualsFourExports137027Evaluator(BaseEvaluator):
    """Judging the four marked exports of the theater visuals task."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        binding_failures = self._binding_failures(params)
        if binding_failures:
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit evaluator binding mismatch",
                {
                    "status": "ERROR",
                    "checks": [{"label": "binding", "passed": False}],
                    "failures": binding_failures,
                    "expected": RUNTIME_PARAMETERS,
                    "observed": params,
                },
            )
        udid = str(params.get("udid") or "").strip()
        simulator_root = Path.home() / DEVICE_ROOT / udid / "data"
        if not udid or not simulator_root.is_dir():
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit simulator photo library is unavailable",
                {
                    "status": "ERROR",
                    "checks": [
                        {
                            "label": "simulator.data_root",
                            "passed": False,
                            "observed": str(simulator_root),
                        }
                    ],
                    "failures": [
                        {
                            "check": "simulator.data_root",
                            "reason": "SIMULATOR_DEVICE_DATA_UNAVAILABLE",
                            "expected": "a readable simulator device data directory",
                            "observed": str(simulator_root),
                        }
                    ],
                    "observed": {"udid_present": bool(udid)},
                },
            )
        try:
            rows = read_simulator_library(simulator_root)
            evidence = validate_exports(rows)
        except Exception as exc:
            return self._result(
                EvalStatus.ERROR,
                "OpenPhotoEdit export verification could not complete: "
                f"{type(exc).__name__}: {exc}",
                {
                    "status": "ERROR",
                    "checks": [{"label": "library.read", "passed": False}],
                    "failures": [
                        {
                            "check": "library.read",
                            "reason": "LIBRARY_READ_ERROR",
                            "exception_type": type(exc).__name__,
                            "message": str(exc),
                        }
                    ],
                    "observed": {"simulator_root": str(simulator_root)},
                },
            )
        evidence["simulator_root"] = str(simulator_root)
        status = EvalStatus.PASS if evidence["status"] == "PASS" else EvalStatus.FAIL
        message = "OpenPhotoEdit theater visuals: four exports match the declared pixels and marker identities" if status == EvalStatus.PASS else "OpenPhotoEdit theater visuals: export verification failed"
        return self._result(status, message, evidence)

    @staticmethod
    def _binding_failures(params: Mapping[str, Any]) -> list[dict[str, Any]]:
        return [
            {
                "field": field,
                "expected": value,
                "observed": params.get(field),
                "reason": "BINDING_MISMATCH",
            }
            for field, value in RUNTIME_PARAMETERS.items()
            if params.get(field) != value
        ]

